using namespace openvst;

namespace {

void check (bool ok, const char* what)
{
    if (! ok)
        throw std::runtime_error (what);
}

void checkMsg (bool ok, const juce::String& what)
{
    if (! ok)
        throw std::runtime_error (what.toStdString());
}

juce::File fixtures() { return juce::File (juce::String (MODULE_STORE_PACKAGE_DIR)); }
juce::File fixture (const char* name) { return fixtures().getChildFile (name); }

juce::File scratchRoot()
{
    static juce::File root = []
    {
        auto dir = juce::File::getSpecialLocation (juce::File::tempDirectory)
                       .getChildFile ("openvst-store-" + juce::Uuid().toString());
        dir.createDirectory();
        return dir;
    }();
    return root;
}

juce::File newStore (const char* name)
{
    auto dir = scratchRoot().getChildFile (name);
    dir.deleteRecursively();
    if (! dir.createDirectory())
        throw std::runtime_error ("cannot create the test store");
    return dir;
}

int versionDirCount (const juce::File& store, const juce::String& id)
{
    const auto idDir = store.getChildFile (id);
    if (! idDir.isDirectory())
        return 0;
    return idDir.getNumberOfChildFiles (juce::File::findDirectories);
}

int stagingCount (const juce::File& store)
{
    const auto staging = store.getChildFile (".staging");
    if (! staging.isDirectory())
        return 0;
    return staging.getNumberOfChildFiles (juce::File::findFilesAndDirectories);
}

juce::MemoryBlock zipEntryBytes (const juce::File& zipFile, const juce::String& name)
{
    juce::ZipFile zip (zipFile);
    const int index = zip.getIndexOfFileName (name);
    checkMsg (index >= 0, "fixture entry missing: " + name);
    std::unique_ptr<juce::InputStream> in (zip.createStreamForEntry (index));
    checkMsg (in != nullptr, "fixture entry unreadable: " + name);
    juce::MemoryOutputStream out;
    out.writeFromInputStream (*in, -1);
    return out.getMemoryBlock();
}

juce::MemoryBlock fileBytes (const juce::File& file)
{
    juce::MemoryBlock block;
    checkMsg (file.existsAsFile(), "expected file is missing: " + file.getFullPathName());
    checkMsg (file.loadFileAsData (block), "cannot read: " + file.getFullPathName());
    return block;
}

constexpr const char* kId = "org.openvst.test.tone";

//==============================================================================
void testSha256()
{
    const auto tmp = scratchRoot().getChildFile ("hash-probe.txt");
    tmp.replaceWithText ("abc");
    checkMsg (ModuleStore::sha256File (tmp) == "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad",
              "sha256 of abc");
    tmp.replaceWithText (juce::String());
    checkMsg (ModuleStore::sha256File (tmp) == "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855",
              "sha256 of the empty file");
    checkMsg (ModuleStore::sha256File (scratchRoot().getChildFile ("does-not-exist")).isEmpty(),
              "missing file has no digest");
    std::cout << "PASS sha256File known vectors\n";
}

void testHappyInstallAndScan()
{
    const auto storeDir = newStore ("store-basic");
    ModuleStore store (storeDir);
    const auto zip = fixture ("valid.openvst.zip");
    checkMsg (zip.existsAsFile(), "fixture missing: valid.openvst.zip");

    const auto zipDigest = ModuleStore::sha256File (zip);
    const auto result = store.install (zip, {}, {});
    checkMsg (result.ok, "install failed: " + result.error);

    const auto& pkg = result.installed.package;
    checkMsg (pkg.id == kId, "module id");
    checkMsg (pkg.version == "1.0.0", "module version");
    checkMsg (pkg.kind == "effect", "module kind");
    checkMsg (pkg.name == "Test Tone", "module name");
    checkMsg (pkg.vendor == "OpenVST", "module vendor");
    checkMsg (pkg.license == "ISC", "module license");
    checkMsg (pkg.packageSHA256 == zipDigest, "package digest is the digest of the exact ZIP");
    checkMsg (pkg.packageSize == zip.getSize(), "package size");
    checkMsg (pkg.sourceRel == "patch/tone.cmajor", "source path");
    checkMsg (pkg.manifestRel == "openvst.json", "manifest path");
    checkMsg (pkg.patchRel == "patch/tone.cmajorpatch", "patch path");
    checkMsg (pkg.uiRel.isEmpty(), "no UI recorded");
    checkMsg (pkg.mainProcessor == "Tone", "main processor");
    checkMsg (pkg.params.size() == 2, "two parameters");
    checkMsg (pkg.params[0].id == "tone.freq" && pkg.params[1].id == "tone.gain", "parameter ids");
    // No endpoint is declared in the manifest, so it defaults to the id, which
    // is the Cmajor endpoint name the loader will look for.
    checkMsg (pkg.params[0].endpoint == "tone.freq" && pkg.params[0].unit == "Hz", "parameter endpoint defaults to the id");
    checkMsg (pkg.params[1].max == 1.0f && pkg.params[1].def == 0.5f, "parameter bounds");

    const auto expectedRoot = storeDir.getChildFile (kId).getChildFile ("1.0.0-" + zipDigest);
    checkMsg (result.installed.root == expectedRoot, "content-addressed install root");
    checkMsg (result.installed.installedAt.isNotEmpty(), "installedAt recorded");

    // The recorded digests must match the archive bytes, not a recomputation
    // over anything the extractor produced by accident.
    const auto archiveSource = zipEntryBytes (zip, "patch/tone.cmajor");
    const auto archiveManifest = zipEntryBytes (zip, "openvst.json");
    checkMsg (pkg.sourceSHA256 == juce::SHA256 (archiveSource).toHexString(), "source digest matches the archive");
    checkMsg (pkg.manifestSHA256 == juce::SHA256 (archiveManifest).toHexString(), "manifest digest matches the archive");
    checkMsg (fileBytes (result.installed.sourceFile) == archiveSource, "installed source bytes are identical");
    checkMsg (fileBytes (result.installed.manifestFile) == archiveManifest, "installed manifest bytes are identical");
    checkMsg (fileBytes (result.installed.patchFile) == zipEntryBytes (zip, "patch/tone.cmajorpatch"), "installed patch bytes");

    const auto installJson = result.installed.root.getChildFile ("install.json");
    checkMsg (installJson.existsAsFile(), "install.json written");
    const auto document = juce::JSON::parse (installJson.loadFileAsString());
    checkMsg (document.isObject(), "install.json parses");
    checkMsg (document.getProperty ("schema", {}).toString() == "openvst.install/0", "install.json schema");
    checkMsg (document.getProperty ("package", {}).getProperty ("sha256", {}).toString() == zipDigest,
              "install.json records the package digest");

    const auto found = store.scan();
    checkMsg (store.problems().isEmpty(), "scan reports no problem: " + store.problems().joinIntoString ("; "));
    checkMsg (found.size() == 1, "scan finds exactly one module");
    checkMsg (found[0].package.id == kId && found[0].package.version == "1.0.0", "scan identity");
    checkMsg (found[0].package.packageSHA256 == zipDigest, "scan digest");
    checkMsg (found[0].root == expectedRoot, "scan root");
    checkMsg (found[0].package.params.size() == 2, "scan restores the parameter table");
    checkMsg (found[0].uiFile == juce::File(), "no UI file");

    std::cout << "PASS install and scan a valid package\n";
}

void testIdempotentReinstall()
{
    const auto storeDir = newStore ("store-idempotent");
    ModuleStore store (storeDir);
    const auto zip = fixture ("valid.openvst.zip");
    const auto digest = ModuleStore::sha256File (zip);

    const auto first = store.install (zip, {}, {});
    checkMsg (first.ok, "first install: " + first.error);
    const auto second = store.install (zip, digest, {});
    checkMsg (second.ok, "idempotent reinstall: " + second.error);
    checkMsg (second.installed.root == first.installed.root, "same install root");
    checkMsg (versionDirCount (storeDir, kId) == 1, "exactly one published directory");
    checkMsg (store.scan().size() == 1, "scan still finds one module");

    std::cout << "PASS idempotent reinstall of identical bytes\n";
}

void testUiPackage()
{
    const auto storeDir = newStore ("store-ui");
    ModuleStore store (storeDir);
    const auto zip = fixture ("valid-ui.openvst.zip");
    const auto result = store.install (zip, ModuleStore::sha256File (zip), {});
    checkMsg (result.ok, "ui install: " + result.error);
    checkMsg (result.installed.package.uiRel == "ui.json", "ui path recorded");
    checkMsg (result.installed.uiFile.existsAsFile(), "ui file extracted");
    checkMsg (fileBytes (result.installed.uiFile) == zipEntryBytes (zip, "ui.json"), "ui bytes identical");

    const auto document = juce::JSON::parse (result.installed.uiFile.loadFileAsString());
    checkMsg (document.getProperty ("schema", {}).toString() == "openvst.ui/0", "ui document schema");

    const auto installJson = juce::JSON::parse (result.installed.root.getChildFile ("install.json").loadFileAsString());
    checkMsg (installJson.getProperty ("ui", {}).getProperty ("path", {}).toString() == "ui.json", "ui path in install.json");
    checkMsg (installJson.getProperty ("ui", {}).getProperty ("sha256", {}).toString()
                  == juce::SHA256 (zipEntryBytes (zip, "ui.json")).toHexString(),
              "ui digest recorded in install.json");

    const auto found = store.scan();
    checkMsg (found.size() == 1 && found[0].package.uiRel == "ui.json", "scan restores the ui path");
    std::cout << "PASS package with a UI document\n";
}

void testMultipleVersions()
{
    const auto storeDir = newStore ("store-versions");
    ModuleStore store (storeDir);

    const auto older = store.install (fixture ("valid.openvst.zip"), {}, {});
    checkMsg (older.ok, "install 1.0.0: " + older.error);
    const auto newer = store.install (fixture ("valid-newer.openvst.zip"), {}, {});
    checkMsg (newer.ok, "install 1.1.0: " + newer.error);
    checkMsg (older.installed.root != newer.installed.root, "versions live side by side");

    const auto found = store.scan();
    checkMsg (found.size() == 2, "scan finds both versions");
    checkMsg (found[0].package.version == "1.0.0" && found[1].package.version == "1.1.0", "deterministic order");

    std::cout << "PASS immutable versions side by side\n";
}

void testSameVersionDifferentBytes()
{
    const auto storeDir = newStore ("store-immutable");
    ModuleStore store (storeDir);

    const auto plain = store.install (fixture ("valid.openvst.zip"), {}, {});
    checkMsg (plain.ok, "install plain package: " + plain.error);

    // valid-ui carries the same (id, version) with different bytes. Accepting
    // it would leave two meanings for one version.
    const auto conflicting = store.install (fixture ("valid-ui.openvst.zip"), {}, {});
    checkMsg (! conflicting.ok, "same version with different bytes is refused");
    checkMsg (versionDirCount (storeDir, kId) == 1, "no second directory for the same version");

    std::cout << "PASS a version stays immutable\n";
}

void testHostileArchives()
{
    struct Case { const char* file; const char* what; };
    const Case cases[] = {
        { "traversal.openvst.zip",      "path traversal" },
        { "absolute.openvst.zip",       "absolute path" },
        { "backslash.openvst.zip",      "backslash path" },
        { "symlink.openvst.zip",        "symbolic link entry" },
        { "worker.openvst.zip",         "worker in the patch" },
        { "mismatch.openvst.zip",       "patch/manifest ID mismatch" },
        { "duplicate-case.openvst.zip", "case-folded duplicate" },
    };

    for (const auto& c : cases)
    {
        const auto storeDir = newStore ((juce::String ("store-bad-") + c.file).toRawUTF8());
        ModuleStore store (storeDir);
        const auto zip = fixture (c.file);
        checkMsg (zip.existsAsFile(), juce::String ("fixture missing: ") + c.file);

        const auto result = store.install (zip, {}, {});
        checkMsg (! result.ok, juce::String (c.what) + " must be refused");
        checkMsg (result.error.isNotEmpty(), juce::String (c.what) + " must give a reason");
        checkMsg (versionDirCount (storeDir, kId) == 0, juce::String (c.what) + " must publish nothing");
        checkMsg (store.scan().empty(), juce::String (c.what) + " must not be visible to scan");
        checkMsg (stagingCount (storeDir) == 0, juce::String (c.what) + " must leave no staging directory");
    }

    std::cout << "PASS hostile archives are refused with no published output\n";
}

void testWrongDigest()
{
    const auto storeDir = newStore ("store-digest");
    ModuleStore store (storeDir);
    const auto zip = fixture ("valid.openvst.zip");

    const auto wrong = juce::String::repeatedString ("0", 64);
    const auto result = store.install (zip, wrong, {});
    checkMsg (! result.ok, "a wrong expected digest is refused");
    checkMsg (versionDirCount (storeDir, kId) == 0, "nothing published");

    const auto malformed = store.install (zip, "not-a-digest", {});
    checkMsg (! malformed.ok, "a malformed expected digest is refused");

    const auto upper = ModuleStore::sha256File (zip).toUpperCase();
    const auto correct = store.install (zip, upper, {});
    checkMsg (correct.ok, "the expected digest is compared case-insensitively: " + correct.error);

    std::cout << "PASS expected digest enforced\n";
}

void testConcurrentInstall()
{
    const auto storeDir = newStore ("store-race");
    const auto zip = fixture ("valid.openvst.zip");
    const auto digest = ModuleStore::sha256File (zip);

    ModuleStore a (storeDir);
    ModuleStore b (storeDir);
    ModuleStore::InstallResult ra, rb;

    std::thread first ([&] { ra = a.install (zip, digest, {}); });
    std::thread second ([&] { rb = b.install (zip, digest, {}); });
    first.join();
    second.join();

    checkMsg (ra.ok, "thread one: " + ra.error);
    checkMsg (rb.ok, "thread two: " + rb.error);
    checkMsg (ra.installed.root == rb.installed.root, "both threads agree on the directory");
    checkMsg (versionDirCount (storeDir, kId) == 1, "exactly one published directory");
    checkMsg (stagingCount (storeDir) == 0, "no staging directory left behind");

    ModuleStore verifier (storeDir);
    checkMsg (verifier.scan().size() == 1, "scan finds one module");
    checkMsg (verifier.problems().isEmpty(), "no scan problem after the race");

    std::cout << "PASS two concurrent installs publish exactly one directory\n";
}

void testStaleStaging()
{
    const auto storeDir = newStore ("store-staging");
    ModuleStore store (storeDir);

    const auto staging = storeDir.getChildFile (".staging").getChildFile ("deadbeef-stale");
    check (staging.createDirectory(), "create a fake stale staging directory");
    check (staging.getChildFile ("install.json").replaceWithText ("{}"), "write a partial install.json");
    staging.setLastModificationTime (juce::Time::getCurrentTime() - juce::RelativeTime::days (2));

    const auto found = store.scan();
    checkMsg (found.empty(), "a staging directory is never a module");
    checkMsg (store.problems().isEmpty(), "a staging directory is not reported as a problem");
    checkMsg (! staging.exists(), "stale staging is cleaned up");

    std::cout << "PASS stale staging is ignored and removed\n";
}

void testRemove()
{
    const auto storeDir = newStore ("store-remove");
    ModuleStore store (storeDir);
    const auto installed = store.install (fixture ("valid.openvst.zip"), {}, {});
    checkMsg (installed.ok, "install: " + installed.error);

    auto outside = installed.installed;
    outside.root = scratchRoot().getChildFile ("elsewhere");
    check (! store.remove (outside), "remove refuses a path outside the store");

    auto forged = installed.installed;
    forged.root = storeDir.getChildFile (kId).getChildFile ("1.0.0-" + juce::String::repeatedString ("0", 64));
    check (! store.remove (forged), "remove refuses a forged digest");
    check (installed.installed.root.isDirectory(), "the real install is untouched");

    auto mismatched = installed.installed;
    mismatched.package.packageSHA256 = juce::String::repeatedString ("0", 64);
    check (! store.remove (mismatched), "remove refuses an identity that does not match its path");

    check (store.remove (installed.installed), "remove deletes the exact installed version");
    check (! installed.installed.root.exists(), "the version directory is gone");
    check (store.scan().empty(), "scan finds nothing afterwards");

    std::cout << "PASS remove is bound to the exact installed version\n";
}

void testCancel()
{
    const auto storeDir = newStore ("store-cancel");
    ModuleStore store (storeDir);
    const auto result = store.install (fixture ("valid.openvst.zip"), {},
                                       [] (double) { return false; });
    checkMsg (! result.ok, "a cancelled install fails");
    checkMsg (versionDirCount (storeDir, kId) == 0, "a cancelled install publishes nothing");
    checkMsg (stagingCount (storeDir) == 0, "a cancelled install leaves no staging directory");
    std::cout << "PASS cancelled install publishes nothing\n";
}

void testScanProblems()
{
    const auto storeDir = newStore ("store-problems");
    ModuleStore store (storeDir);
    check (storeDir.getChildFile ("not-a-module").createDirectory(), "stray directory");
    check (storeDir.getChildFile ("org.openvst.test.broken").getChildFile ("junk").createDirectory(),
           "malformed version directory");

    const auto found = store.scan();
    checkMsg (found.empty(), "malformed entries are not modules");
    checkMsg (store.problems().size() == 2, "both malformed entries are reported");
    std::cout << "PASS scan reports malformed store entries\n";
}

void testDownloadGuards()
{
    const auto storeDir = newStore ("store-download");
    const auto part = storeDir.getChildFile ("package.part");
    const auto digest = juce::String::repeatedString ("a", 64);

    const auto badScheme = ModuleStore::download (juce::URL ("file:///tmp/package.zip"), part, digest, {});
    checkMsg (! badScheme.ok, "a non-http URL is refused");
    checkMsg (! badScheme.error.isEmpty(), "a non-http URL gives a reason");
    checkMsg (! part.existsAsFile(), "no part file for a refused URL");

    // The digest is checked before any request is attempted, so port 9 is
    // never contacted.
    const auto badDigest = ModuleStore::download (juce::URL ("http://127.0.0.1:9/package.zip"),
                                                  part, "not-a-digest", {});
    checkMsg (! badDigest.ok, "a malformed expected digest is refused");
    checkMsg (! part.existsAsFile(), "no part file without a usable digest");

    std::cout << "PASS download refuses bad input before touching the network\n";
}

} // namespace

int main()
{
    try
    {
        checkMsg (fixtures().isDirectory(), juce::String ("fixture directory missing: ") + MODULE_STORE_PACKAGE_DIR);

        testSha256();
        testHappyInstallAndScan();
        testIdempotentReinstall();
        testUiPackage();
        testMultipleVersions();
        testSameVersionDifferentBytes();
        testHostileArchives();
        testWrongDigest();
        testConcurrentInstall();
        testStaleStaging();
        testRemove();
        testCancel();
        testScanProblems();
        testDownloadGuards();

        scratchRoot().deleteRecursively();
        std::cout << "ALL MODULE STORE TESTS PASSED\n";
        return 0;
    }
    catch (const std::exception& e)
    {
        std::cout << "FAIL: " << e.what() << "\n";
        return 1;
    }
}
